const input = require("fs").readFileSync(0, "utf8");

function robHouses(amounts) {
  // best[i] is the most money you can take from the first i houses.
  const best = new Array(amounts.length + 1).fill(0);
  for (let i = 0; i < amounts.length; i++) {
    const skip = best[i];
    const take = amounts[i] + (i > 0 ? best[i - 1] : 0);
    best[i + 1] = Math.max(skip, take);
  }
  return best[amounts.length];
}

const [n, ...amounts] = input.trim().split(/\s+/).map(Number);
console.log(robHouses(amounts.slice(0, n)));

