package main

import "fmt"

func robHouses(amounts []int) int {
	// best[i] is the most money you can take from the first i houses.
	best := make([]int, len(amounts)+1)
	for i, amount := range amounts {
		skip := best[i]
		take := amount
		if i > 0 {
			take += best[i-1]
		}
		if take > skip {
			best[i+1] = take
		} else {
			best[i+1] = skip
		}
	}
	return best[len(amounts)]
}

func main() {
	var n int
	fmt.Scan(&n)
	amounts := make([]int, n)
	for i := range amounts {
		fmt.Scan(&amounts[i])
	}
	fmt.Println(robHouses(amounts))
}

