import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function robHouses(amounts: number[]): number {
  // best[i] is the most money you can take from the first i houses.
  const best: number[] = new Array<number>(amounts.length + 1).fill(0);
  for (const [i, amount] of amounts.entries()) {
    const skip = best[i] ?? 0;
    // Before the first house, best[-1] is undefined: nothing to add.
    const take = amount + (best[i - 1] ?? 0);
    best[i + 1] = Math.max(skip, take);
  }
  return best[amounts.length] ?? 0;
}

const [n = 0, ...amounts] = input.trim().split(/\s+/).map(Number);
console.log(robHouses(amounts.slice(0, n)));
